contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value);

        uint beforeBalance = address(c).balance;

        bool reverted;
        c.sendMoney(target, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterBalance = address(c).balance;

        assert(value <= beforeBalance || reverted || afterBalance == beforeBalance);
    }

    receive() external payable {}
}

